sys_script.script:
(function () {
    var supplierValue = current.getValue('supplier');

    // Only auto-select if no supplier is set
    if (supplierValue) {
        return;
    }

    var supplierGr = new GlideRecord('x_2056099_indust_0_supplier');
    supplierGr.addQuery('status', 'active');
    supplierGr.addQuery('availability', 'available');
    supplierGr.orderByDesc('cumulative_score');
    supplierGr.setLimit(1);
    supplierGr.query();

    if (supplierGr.next()) {
        current.setValue('supplier', supplierGr.getUniqueValue());
        gs.addInfoMessage('Auto-selected supplier: ' + supplierGr.getValue('name') + ' (Score: ' + supplierGr.getValue('cumulative_score') + ')');
    } else {
        gs.addErrorMessage('No available suppliers found. Please add an active supplier before creating orders.');
        current.setAbortAction(true);
    }
})();
